1	<script lang="ts">
2		import { onMount, untrack } from 'svelte';
3		import { page } from '$app/stores';
4		import { goto } from '$app/navigation';
5		import { resolve } from '$app/paths';
6		import { supabase } from '$lib/supabaseClient';
7		import { getSignedReceiptUrl } from '$lib/utils/signedUrl';
8		import { ReceiptService } from '$lib/services/ReceiptService';
9		import { CategoryService } from '$lib/services/CategoryService';
10		import { ExpenseService } from '$lib/services/ExpenseService';
11		import type { ReceiptRow } from '$lib/models/Receipt';
12		import type { Category } from '$lib/types/Category';
13		import { detectDuplicates } from '$lib/utils/duplicateDetection';
14		import { getDuplicateInfo, isDuplicate } from '$lib/utils/duplicateHelpers';
15		import { getValidDate } from '$lib/utils/dateValidation';
16		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
17		import { Datepicker } from 'flowbite-svelte';
18		import { toDate, toISODateString } from '$lib/utils/dateConversion';
19		import { formatCurrency, formatCurrencyWithEstimate } from '$lib/utils/formatCurrency';
20		import ReceiptEditModal from '$lib/components/ReceiptEditModal.svelte';
21	
22	
23		let allReceipts: ReceiptRow[] = $state([]);
24		let sort: 'transaction_date' | 'merchant_name' | 'total_amount' = $state('transaction_date');
25		let direction: 'asc' | 'desc' = $state('desc');
26		let error: string | null = $state(null);
27		let uploading = $state(false);
28		let manual = $state({ merchant_name: '', total_amount: '', transaction_date: '' } as any);
29		let deleting = $state(new Set<string>());
30	
31		// #{#rct1b} Receipt edit modal state
32		let editingReceipt: ReceiptRow | null = $state(null);
33		let showEditModal = $state(false);
34		let isSavingReceipt = $state(false);
35		let editModalError: string | null = $state(null);
36	
37		// #{#rmc2a} Category state for ReceiptEditModal
38		let categories: Category[] = $state([]);
39		let familyId: string | null = $state(null);
40		let categoryMap: Record<string, Category | null> = $state({});
41	
42		// #{#blk1b} Selection state management
43		let selectedReceiptIds: Set<string> = $state(new Set<string>());
44		let showDeleteConfirm = $state(false);
45		let isDeleting = $state(false);
46		let successMessage: string | null = $state(null);
47		let errorMessage: string | null = $state(null);
48	
49		// #{#sdf2a} Read date filters from URL query parameters
50		let urlDateFrom = $derived(getValidDate($page.url.searchParams.get('dateFrom')));
51		let urlDateTo = $derived(getValidDate($page.url.searchParams.get('dateTo')));
52	
53		// Client-side filters - temporary values for inputs
54		let tempFilterDateFrom = $state(getValidDate($page.url.searchParams.get('dateFrom')));
55		let tempFilterDateTo = $state(getValidDate($page.url.searchParams.get('dateTo')));
56		let tempFilterMerchant = $state('');
57		let tempFilterAmountMin = $state('');
58		let tempFilterAmountMax = $state('');
59	
60		// Sync temp date values when URL changes
61		$effect(() => {
62			tempFilterDateFrom = urlDateFrom;
63			tempFilterDateTo = urlDateTo;
64		});
65	
66		// Active filter values used for filtering (non-date filters only)
67		let filterMerchant = $state('');
68		let filterAmountMin = $state('');
69		let filterAmountMax = $state('');
70	
71		// #{#dtv3a} Needs Review filter state
72		let filterNeedsReview = $state(false);
73	
74		// #{#dup5a} Duplicate receipts filter state
75		let filterDuplicates = $state(false);
76	
77		async function deleteReceipt(r: ReceiptRow): Promise<void> {
78			if (!confirm('Delete this receipt? This will remove the record and the stored file.')) return;
79			deleting.add(r.id);
80			// reassign to trigger reactivity for Set updates
81			deleting = new Set(deleting);
82			error = null;
83			try {
84				await ReceiptService.get().delete(r.id, r.receipt_image_path);
85				allReceipts = allReceipts.filter((x) => x.id !== r.id);
86			} catch (e: any) {
87				error = e?.message ?? 'Failed to delete receipt';
88			} finally {
89				deleting.delete(r.id);
90				deleting = new Set(deleting);
91			}
92		}
93	
94		async function load(): Promise<void> {
95			error = null;
96			try {
97				console.log('[DEBUG] Loading receipts...');
98				const user = (await supabase.auth.getUser()).data.user;
99				console.log('[DEBUG] Current user:', user?.id, user?.email);
100				allReceipts = await ReceiptService.get().list(sort, direction);
101				console.log('[DEBUG] Loaded receipts:', allReceipts.length);
102			} catch (e: any) {
103				console.error('[DEBUG] Error loading receipts:', e);
104				error = e?.message ?? 'Failed to load receipts';
105			}
106		}
107	
108		onMount(async () => {
109			await load();
110			await loadCategories();
111		});
112	
113		function sortBy(field: typeof sort): void {
114			if (sort === field) direction = direction === 'asc' ? 'desc' : 'asc';
115			else {
116				sort = field;
117				direction = 'asc';
118			}
119			load();
120		}
121	
122		async function onFilesChanged(e: Event): Promise<void> {
123			const input = e.target as HTMLInputElement;
124			const files = input.files;
125			if (!files) return;
126			uploading = true;
127			error = null;
128	
129			// #{#dtv2a} Upload receipts — suspicious dates are silently flagged, no dialog shown
130			// Each file is processed independently so one failure doesn't abort the batch.
131			const failures: string[] = [];
132			for (const file of files) {
133				try {
134					const receipt = await ReceiptService.get().uploadAndCreate(file);
135					allReceipts = [receipt, ...allReceipts];
136				} catch (err: any) {
137					console.error('Failed to upload receipt', file.name, err);
138					failures.push(`${file.name}: ${err?.message ?? 'Failed to upload'}`);
139				}
140			}
141			if (failures.length > 0) {
142				error = `Failed ${failures.length} of ${files.length} receipt(s):\n${failures.join('\n')}`;
143			}
144			uploading = false;
145	
146			input.value = '';
147		}
148	
149		// #{#sec1a} Signed URL cache for receipt images
150		let signedUrls: Record<string, string> = $state({});
151	
152		// #{#sec1a} Load signed URLs whenever allReceipts changes
153		// Uses untrack to read signedUrls without creating a reactive loop
154		$effect(() => {
155			const paths = allReceipts
156				.map((r) => r.receipt_image_path)
157				.filter((p): p is string => !!p);
158			untrack(() => loadSignedUrls(paths));
159		});
160	
161		async function loadSignedUrls(paths: string[]) {
162			const cached = signedUrls;
163			const newUrls: Record<string, string> = {};
164			await Promise.all(
165				paths.map(async (path) => {
166					if (cached[path]) {
167						newUrls[path] = cached[path];
168						return;
169					}
170					const url = await getSignedReceiptUrl(path);
171					if (url) newUrls[path] = url;
172				})
173			);
174			signedUrls = newUrls;
175		}
176	
177		function getImageUrl(path: string | null): string | null {
178			if (!path) return null;
179			return signedUrls[path] ?? null;
180		}
181	
182		// #{#rct1a} Open edit modal when row is clicked
183		function openEditModal(receipt: ReceiptRow) {
184			editingReceipt = { ...receipt };
185			showEditModal = true;
186			editModalError = null;
187		}
188	
189		// #{#rct4b} Close edit modal
190		function closeEditModal() {
191			showEditModal = false;
192			editingReceipt = null;
193			editModalError = null;
194			isSavingReceipt = false;
195		}
196	
197		// #{#rct5a} Save receipt changes from modal
198		async function handleSaveReceipt(updatedReceipt: ReceiptRow) {
199			isSavingReceipt = true;
200			editModalError = null;
201	
202			try {
203				const patch = {
204					merchant_name: updatedReceipt.merchant_name,
205					total_amount: updatedReceipt.total_amount,
206					transaction_date: updatedReceipt.transaction_date,
207					tax: updatedReceipt.tax,
208					currency: updatedReceipt.currency,
209					exchange_rate_to_cad: updatedReceipt.exchange_rate_to_cad,
210					credit_card_name: updatedReceipt.credit_card_name,
211					credit_card_last_4: updatedReceipt.credit_card_last_4,
212					// #{#dtv2d} Preserve confirmed suspicious_date status
213					suspicious_date: updatedReceipt.suspicious_date
214				};
215	
216				const saved = await ReceiptService.get().update(updatedReceipt.id, patch);
217				allReceipts = allReceipts.map((r) => (r.id === saved.id ? saved : r));
218	
219				// #{#rct5b} Show success message
220				successMessage = 'Receipt updated successfully';
221				setTimeout(() => {
222					successMessage = null;
223				}, 3000);
224	
225				closeEditModal();
226			} catch (e: any) {
227				editModalError = e?.message ?? 'Failed to save receipt';
228			} finally {
229				isSavingReceipt = false;
230			}
231		}
232	
233		// #{#rmc2a} Load family categories for CategoryDropdown in edit modal
234		async function loadCategories() {
235			try {
236				familyId = await getDefaultFamilyId();
237				if (!familyId) return;
238	
239				const categoryService = new CategoryService(supabase);
240				categories = (await categoryService.getFamilyCategories(familyId)) as Category[];
241	
242				// Load category assignments for all receipts
243				const expenseService = new ExpenseService(supabase);
244				const user = (await supabase.auth.getUser()).data.user;
245				if (user) {
246					const expenses = await expenseService.getExpenses(user.id);
247					const map: Record<string, Category | null> = {};
248					for (const exp of expenses) {
249						if (exp.category_id) {
250							const cat = categories.find((c) => c.id === exp.category_id);
251							map[exp.receipt_id] = cat ?? null;
252						}
253					}
254					categoryMap = map;
255				}
256			} catch (err) {
257				console.error('Error loading categories:', err);
258			}
259		}
260	
261		// #{#rmc2a} Handle category change from ReceiptEditModal
262		async function handleCategoryChange(receiptId: string, category: Category) {
263			if (!familyId) return;
264	
265			try {
266				const expenseService = new ExpenseService(supabase);
267				await expenseService.assignCategory(receiptId, category.id, 'manual');
268	
269				// Create vendor rule if none exists
270				const receipt = allReceipts.find((r) => r.id === receiptId);
271				if (receipt?.merchant_name) {
272					const existingRule = await expenseService.getVendorRule(familyId, receipt.merchant_name);
273					if (!existingRule) {
274						await expenseService.createVendorRule(familyId, receipt.merchant_name, category.id);
275					}
276				}
277	
278				// Update local category map
279				categoryMap = { ...categoryMap, [receiptId]: category };
280			} catch (err) {
281				console.error('Error assigning category:', err);
282			}
283		}
284	
285		async function createManual(e: Event): Promise<void> {
286			e.preventDefault();
287			try {
288				const created = await ReceiptService.get().createManual({
289					merchant_name: manual.merchant_name,
290					total_amount: parseFloat(manual.total_amount),
291					transaction_date: manual.transaction_date
292				});
293				allReceipts = [created, ...allReceipts];
294				manual = { merchant_name: '', total_amount: '', transaction_date: '' };
295			} catch (e: any) {
296				error = e?.message ?? 'Failed to create receipt';
297			}
298		}
299	
300		function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
301			// #{#dup5a} Pre-compute duplicate IDs when filter is active
302			let dupeIds: Set<string> | null = null;
303			if (filterDuplicates) {
304				const dupes = detectDuplicates(rcts);
305				dupeIds = new Set<string>();
306				for (const ids of dupes.values()) {
307					for (const id of ids) dupeIds.add(id);
308				}
309			}
310	
311			return rcts.filter((r) => {
312				// #{#dtv3a} Filter by suspicious_date (Needs Review)
313				if (filterNeedsReview && !r.suspicious_date) return false;
314	
315				// #{#dup5a} Filter by duplicate status
316				if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;
317	
318				// #{#sdf1b} Filter by date range using URL parameters
319				if (urlDateFrom && r.transaction_date && r.transaction_date < urlDateFrom) return false;
320				if (urlDateTo && r.transaction_date && r.transaction_date > urlDateTo) return false;
321	
322				// Filter by merchant name (local state)
323				if (filterMerchant) {
324					const merchantSearch = filterMerchant.toLowerCase();
325					const merchant = (r.merchant_name || '').toLowerCase();
326					if (!merchant.includes(merchantSearch)) return false;
327				}
328	
329				// Filter by amount range (local state)
330				if (filterAmountMin && r.total_amount !== null) {
331					const minAmount = parseFloat(filterAmountMin);
332					if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
333				}
334				if (filterAmountMax && r.total_amount !== null) {
335					const maxAmount = parseFloat(filterAmountMax);
336					if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
337				}
338	
339				return true;
340			});
341		}
342	
343		function applyFilterValues(): void {
344			// #{#sdf2a} Update URL with date filters
345			const params = new URLSearchParams($page.url.searchParams);
346	
347			if (tempFilterDateFrom) params.set('dateFrom', tempFilterDateFrom);
348			else params.delete('dateFrom');
349	
350			if (tempFilterDateTo) params.set('dateTo', tempFilterDateTo);
351			else params.delete('dateTo');
352	
353			goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });
354	
355			// Apply non-date filters locally
356			filterMerchant = tempFilterMerchant;
357			filterAmountMin = tempFilterAmountMin;
358			filterAmountMax = tempFilterAmountMax;
359		}
360	
361		function clearClientFilters(): void {
362			// #{#sdf2a} Clear URL date filters
363			const params = new URLSearchParams($page.url.searchParams);
364			params.delete('dateFrom');
365			params.delete('dateTo');
366			goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });
367	
368			// Clear local filters
369			tempFilterMerchant = '';
370			tempFilterAmountMin = '';
371			tempFilterAmountMax = '';
372			filterMerchant = '';
373			filterAmountMin = '';
374			filterAmountMax = '';
375	
376			// #{#dtv3a} Clear Needs Review filter
377			filterNeedsReview = false;
378	
379			// #{#dup5a} Clear Duplicates filter
380			filterDuplicates = false;
381		}
382	
383		let receipts = $derived((() => {
384			// Explicitly depend on all filter variables (URL-based date filters + local filters)
385			const deps = [urlDateFrom, urlDateTo, filterMerchant, filterAmountMin, filterAmountMax, filterDuplicates];
386			const filtered = applyClientFilters(allReceipts);
387			console.log('[DEBUG] Filtering receipts:', {
388				allReceiptsCount: allReceipts.length,
389				filteredCount: filtered.length,
390				filters: { urlDateFrom, urlDateTo, filterMerchant, filterAmountMin, filterAmountMax, filterNeedsReview, filterDuplicates }
391			});
392			return filtered;
393		})());
394	
395		// #{#dup1b} #{#dup2b} Detect duplicates on filtered receipts
396		let duplicateGroups = $derived(detectDuplicates(receipts));
397	
398		// #{#dup5a} Detect duplicates on ALL receipts for badge count
399		let allDuplicateGroups = $derived(detectDuplicates(allReceipts));
400		let duplicateReceiptCount = $derived(
401			Array.from(allDuplicateGroups.values()).reduce((sum, ids) => sum + ids.length, 0)
402		);
403	
404		let hasActiveFilters = $derived(
405			urlDateFrom ||
406			urlDateTo ||
407			filterMerchant ||
408			filterAmountMin ||
409			filterAmountMax ||
410			filterNeedsReview ||
411			filterDuplicates
412		);
413	
414		// #{#blk1a} #{#blk1b} Selection functions
415		function toggleSelection(id: string): void {
416			if (selectedReceiptIds.has(id)) {
417				selectedReceiptIds.delete(id);
418			} else {
419				selectedReceiptIds.add(id);
420			}
421			selectedReceiptIds = new Set(selectedReceiptIds); // Trigger reactivity
422		}
423	
424		function selectAll(): void {
425			if (isAllSelected) {
426				selectedReceiptIds = new Set<string>();
427			} else {
428				selectedReceiptIds = new Set(receipts.map((r) => r.id));
429			}
430		}
431	
432		// #{#blk4b} Clear selection
433		function clearSelection(): void {
434			selectedReceiptIds = new Set<string>();
435		}
436	
437		// #{#blk2a} Check if all visible receipts are selected
438		let isAllSelected = $derived(receipts.length > 0 && receipts.every((r) => selectedReceiptIds.has(r.id)));
439	
440		// #{#blk1a} Check if some (but not all) receipts are selected
441		let isIndeterminate = $derived(
442			selectedReceiptIds.size > 0 &&
443			receipts.some((r) => selectedReceiptIds.has(r.id)) &&
444			!isAllSelected
445		);
446	
447		// #{#blk2b} Bulk delete confirmation
448		function confirmBulkDelete(): void {
449			showDeleteConfirm = true;
450		}
451	
452		// #{#blk3a} #{#blk3b} Execute bulk delete with optimistic update
453		async function executeBulkDelete(): Promise<void> {
454			isDeleting = true;
455			showDeleteConfirm = false;
456			errorMessage = null;
457			successMessage = null;
458	
459			// Optimistic update - remove from UI immediately
460			const idsToDelete = Array.from(selectedReceiptIds);
461			const originalReceipts = [...allReceipts];
462	
463			// #{#blk3b} Optimistic UI update
464			allReceipts = allReceipts.filter((r) => !selectedReceiptIds.has(r.id));
465	
466			try {
467				// #{#blk3a} Call bulk delete service
468				await ReceiptService.get().bulkDeleteReceipts(idsToDelete);
469	
470				// #{#blk6b} Success feedback
471				successMessage = `Successfully deleted ${idsToDelete.length} receipt${idsToDelete.length === 1 ? '' : 's'}`;
472				clearSelection();
473	
474				// Auto-dismiss success message after 4 seconds
475				setTimeout(() => {
476					successMessage = null;
477				}, 4000);
478			} catch (e: any) {
479				// #{#blk3b} Rollback on failure
480				allReceipts = originalReceipts;
481				errorMessage = e?.message ?? 'Failed to delete receipts. Please try again.';
482	
483				// Keep error message visible longer
484				setTimeout(() => {
485					errorMessage = null;
486				}, 8000);
487			} finally {
488				isDeleting = false;
489			}
490		}
491	
492		// #{#blk1b} Clear invalid selections when receipts are deleted individually
493		$effect(() => {
494			const validIds = new Set(allReceipts.map((r) => r.id));
495			const filtered = new Set(Array.from(selectedReceiptIds).filter((id) => validIds.has(id)));
496			if (filtered.size !== selectedReceiptIds.size) {
497				selectedReceiptIds = filtered;
498			}
499		});
500	</script>
501	
502	<div class="mb-4 flex items-center justify-between">
503		<h1 class="text-xl font-semibold">Receipts</h1>
504		<label
505			class="inline-flex cursor-pointer items-center gap-2 rounded border bg-blue-600 px-3 py-2 text-sm text-white hover:bg-blue-700"
506		>
507			<input
508				class="hidden"
509				type="file"
510				multiple
511				onchange={onFilesChanged}
512				accept="image/jpeg,image/png,image/heic,application/pdf"
513			/>
514			{uploading ? 'Uploading…' : 'Upload receipts'}
515		</label>
516	</div>
517	
518	{#if error}
519		<div class="mb-4 rounded border border-red-200 bg-red-50 p-2 whitespace-pre-wrap text-red-700">
520			{error}
521		</div>
522	{/if}
523	
524	<!-- #{#blk6b} Success/Error notifications -->
525	{#if successMessage}
526		<div
527			class="mb-4 rounded border border-green-200 bg-green-50 p-3 text-green-800 shadow-sm"
528			role="status"
529			aria-live="polite"
530		>
531			<div class="flex items-center gap-2">
532				<svg class="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
533					<path
534						stroke-linecap="round"
535						stroke-linejoin="round"
536						stroke-width="2"
537						d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
538					/>
539				</svg>
540				<span>{successMessage}</span>
541			</div>
542		</div>
543	{/if}
544	
545	{#if errorMessage}
546		<div
547			class="mb-4 rounded border border-red-200 bg-red-50 p-3 text-red-800 shadow-sm"
548			role="alert"
549			aria-live="assertive"
550		>
551			<div class="flex items-center gap-2">
552				<svg class="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
553					<path
554						stroke-linecap="round"
555						stroke-linejoin="round"
556						stroke-width="2"
557						d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
558					/>
559				</svg>
560				<span>{errorMessage}</span>
561			</div>
562		</div>
563	{/if}
564	
565	<!-- Filters -->
566	<div class="mb-4 rounded border bg-white p-4 shadow-sm">
567		<h2 class="mb-3 font-semibold">Filters</h2>
568		<div class="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-5">
569			<div>
570				<label class="mb-1 block text-sm font-medium">Date From</label>
571				<Datepicker
572					value={toDate(tempFilterDateFrom)}
573					onselect={(date) => { tempFilterDateFrom = toISODateString(date); }}
574					placeholder="From date"
575					inputmode="text"
576				/>
577			</div>
578			<div>
579				<label class="mb-1 block text-sm font-medium">Date To</label>
580				<Datepicker
581					value={toDate(tempFilterDateTo)}
582					onselect={(date) => { tempFilterDateTo = toISODateString(date); }}
583					placeholder="To date"
584					inputmode="text"
585				/>
586			</div>
587			<div>
588				<label class="mb-1 block text-sm font-medium">Merchant Name</label>
589				<input
590					type="text"
591					bind:value={tempFilterMerchant}
592					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
593					placeholder="Search merchant..."
594				/>
595			</div>
596			<div>
597				<label class="mb-1 block text-sm font-medium">Min Amount ($)</label>
