704		/**
705		 * #{#cre1a} #{#cre4b} Handle PDF receipt export
706		 * #{#cre1b} Respects current filters (exports filteredExpenses)
707		 * #{#cre4a} Shows progress and supports cancellation
708		 */
709		async function handleExportPDF() {
710			if (!PDFExportService.shouldEnablePDFExport({
711				filteredExpensesCount: filteredExpenses.length,
712				selectedCategoryIds,
713				showUncategorizedOnly,
714				isExporting: isExportingPDF
715			})) {
716				return;
717			}
718	
719			isExportingPDF = true;
720			pdfExportProgress = 'Preparing receipt data...';
721			pdfAbortController = new AbortController();
722	
723			try {
724				// #{#cre1b} Build category names for the selected filters
725				const selectedCategories = categories.filter((c) =>
726					selectedCategoryIds.includes(c.id)
727				);
728				const categoryNames = selectedCategories.map((c) => c.name);
729	
730				// #{#cre3a} Fetch receipt images via signed URLs
731				const fetchImageFn = async (path: string): Promise<Uint8Array | null> => {
732					const signedUrl = await getSignedReceiptUrl(path, 300); // 5 min expiry
733					if (!signedUrl) return null;
734					const response = await fetch(signedUrl);
735					if (!response.ok) return null;
736					const buffer = await response.arrayBuffer();
737					return new Uint8Array(buffer);
738				};
739	
740				// #{#cre1b} Build date range from URL filters
741				const dateRange =
742					urlDateFrom && urlDateTo
743						? { start: urlDateFrom, end: urlDateTo }
744						: urlDateFrom
745							? { start: urlDateFrom, end: urlDateFrom }
746							: null;
747	
748				const pdfBytes = await pdfService.generateReceiptPDF(filteredExpenses, {
749					categories: selectedCategories,
750					dateRange,
751					fetchImageFn,
752					abortSignal: pdfAbortController.signal,
753					onProgress: (step: string) => {
754						pdfExportProgress = step;
755					}
756				});
757	
758				// #{#cre3b} Generate filename and download
759				const filename = pdfService.generateFilename(categoryNames, dateRange);
760				pdfService.downloadPDF(pdfBytes, filename);
761	
762				// #{#cre4a} Success feedback
763				const totalAmount = pdfService.calculateSubtotal(filteredExpenses);
764				showToast(
765					`PDF exported: ${filteredExpenses.length} receipt${filteredExpenses.length !== 1 ? 's' : ''} across ${categoryNames.length} categor${categoryNames.length !== 1 ? 'ies' : 'y'}, ${pdfService.formatAmount(totalAmount)} total`,
766					'success'
767				);
768			} catch (err) {
769				if (err instanceof Error && /abort|cancel/i.test(err.message)) {
770					showToast('PDF export cancelled', 'success');
771				} else {
772					console.error('Error exporting PDF:', err);
773					showToast(
774						`Failed to generate PDF: ${err instanceof Error ? err.message : 'Unknown error'}`,
775						'error'
776					);
777				}
778			} finally {
779				isExportingPDF = false;
780				pdfExportProgress = '';
781				pdfAbortController = null;
782			}
783		}
