131		/**
132		 * Parse CSV/XLS/XLSX file and return parsed transactions - #{#xls2b}
133		 */
134		async parseCSV(
135			file: File,
136			creditCardType: CreditCardType
137		): Promise<{
138			transactions: ParsedTransaction[];
139			errors: string[];
140			detectedType?: CreditCardType;
141		}> {
142			return new Promise((resolve, reject) => {
143				const reader = new FileReader();
144	
145				reader.onload = (e) => {
146					try {
147						let csvContent: string;
148	
149						if (isExcelFile(file)) {
150							const buffer = e.target?.result as ArrayBuffer;
151							csvContent = convertExcelToCSV(buffer);
152						} else {
153							csvContent = e.target?.result as string;
154						}
155	
156						// Get the appropriate parser
157						const parser = CSVParserFactory.getParser(creditCardType);
158	
159						// Validate format
160						if (!parser.validateFormat(csvContent)) {
161							resolve({
162								transactions: [],
163								errors: [
164									`The file does not match the expected format for ${creditCardType}. Please verify you selected the correct credit card type.`
165								]
166							});
167							return;
168						}
169	
170						// Parse the CSV
171						const result = parser.parse(csvContent);
172						resolve({
173							transactions: result.transactions,
174							errors: result.errors
175						});
176					} catch (error: any) {
177						reject(new Error(`Failed to parse file: ${error.message || 'Unknown error'}`));
178					}
179				};
180	
181				reader.onerror = () => {
182					reject(new Error('Failed to read file'));
183				};
184	
185				if (isExcelFile(file)) {
186					reader.readAsArrayBuffer(file);
187				} else {
188					reader.readAsText(file);
189				}
190			});
191		}
