function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
    // #{#dup5a} Pre-compute duplicate IDs when filter is active
    let dupeIds: Set<string> | null = null;
    if (filterDuplicates) {
        const dupes = detectDuplicates(rcts);
        dupeIds = new Set<string>();
        for (const ids of dupes.values()) {
            for (const id of ids) dupeIds.add(id);
        }
    }

    return rcts.filter((r) => {
        // #{#dtv3a} Filter by suspicious_date (Needs Review)
        if (filterNeedsReview && !r.suspicious_date) return false;

        // #{#dup5a} Filter by duplicate status
        if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;

        // #{#sdf1b} Filter by date range using URL parameters
        if (urlDateFrom && r.transaction_date && r.transaction_date < urlDateFrom) return false;
        if (urlDateTo && r.transaction_date && r.transaction_date > urlDateTo) return false;

        // Filter by merchant name (local state)
        if (filterMerchant) {
            const merchantSearch = filterMerchant.toLowerCase();
            const merchant = (r.merchant_name || '').toLowerCase();
            if (!merchant.includes(merchantSearch)) return false;
        }

        // Filter by amount range (local state)
        if (filterAmountMin && r.total_amount !== null) {
            const minAmount = parseFloat(filterAmountMin);
            if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
        }
        if (filterAmountMax && r.total_amount !== null) {
            const maxAmount = parseFloat(filterAmountMax);
            if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
        }

        return true;
    });
}

function applyFilterValues(): void {
    // #{#sdf2a} Update URL with date filters
    const params = new URLSearchParams($page.url.searchParams);

    if (tempFilterDateFrom) params.set('dateFrom', tempFilterDateFrom);
    else params.delete('dateFrom');

    if (tempFilterDateTo) params.set('dateTo', tempFilterDateTo);
    else params.delete('dateTo');

    goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });

    // Apply non-date filters locally
    filterMerchant = tempFilterMerchant;
    filterAmountMin = tempFilterAmountMin;
    filterAmountMax = tempFilterAmountMax;
}

function clearClientFilters(): void {
    // #{#sdf2a} Clear URL date filters
    const params = new URLSearchParams($page.url.searchParams);
    params.delete('dateFrom');
    params.delete('dateTo');
    goto(`${$page.url.pathname}?${params.toString()}`, { replaceState: true, keepFocus: true });

    // Clear local filters
    tempFilterMerchant = '';
    tempFilterAmountMin = '';
    tempFilterAmountMax = '';
    filterMerchant = '';
    filterAmountMin = '';
    filterAmountMax = '';

    // #{#dtv3a} Clear Needs Review filter
    filterNeedsReview = false;

    // #{#dup5a} Clear Duplicates filter
    filterDuplicates = false;
}
